function 应用信息() {
  const app = Application;
  const s = Sheets.Item(1);
  s.Range("A1").Value2 = 1;
  s.Range("A2").Value2 = 2;
  console.log(app.Version);
  console.log(app.WorksheetFunction.Sum(s.Range("A1:A2")));
}

function 快速写入() {
  const app = Application;
  const s = Sheets.Item(1);
  app.ScreenUpdating = false;
  for (let i = 1; i <= 100; i++) {
    s.Range("A" + i).Value2 = i;
  }
  app.ScreenUpdating = true;
}

function 取表() {
  const first = Worksheets.Item(1);
  const data = Worksheets.Item("数据");
  console.log(first.Name);
  console.log(data.Range("A1").Value2);
}

function 列表() {
  const n = Worksheets.Count;
  for (let i = 1; i <= n; i++) {
    console.log(i, Worksheets.Item(i).Name);
  }
}

function 偏移() {
  const s = Sheets.Item(1);
  const r = s.Range("A1").Offset(2, 2);
  r.Value2 = "到了 C3";
  console.log(r.Address);
}

function 扩区域() {
  const s = Sheets.Item(1);
  const r = s.Range("A1").Resize(3, 2);
  r.Value2 = [[1, 2], [3, 4], [5, 6]];
  console.log(r.Address);
}

function 看范围() {
  const ws = ActiveSheet;
  const ur = ws.UsedRange;
  console.log(ur.Address);
  console.log(ur.Rows.Count, ur.Columns.Count);
}

function 追加() {
  const ws = ActiveSheet;
  const last = ws.UsedRange.Row + ws.UsedRange.Rows.Count - 1;
  ws.Range("A" + (last + 1)).Value2 = "新记录";
}

function 查找() {
  const s = Sheets.Item(1);
  const cell = s.Range("A:A").Find("张三");
  if (cell) {
    cell.Offset(0, 1).Value2 = 100;
  } else {
    alert("没找到");
  }
}

function 找全部() {
  const s = Sheets.Item(1);
  const rng = s.Range("A:A");
  let cell = rng.Find("张三");
  while (cell) {
    console.log(cell.Address);
    cell = rng.FindNext(cell);
  }
}

function 筛选() {
  const s = Sheets.Item(1);
  const r = s.Range("A1:C10");
  r.AutoFilter(2, ">90");
}

function 取消筛选() {
  const s = Sheets.Item(1);
  if (s.AutoFilterMode) {
    s.AutoFilterMode = false;
  }
}

function 排序() {
  const s = Sheets.Item(1);
  const r = s.Range("A1:C10");
  r.Sort(s.Range("B2"), 2);
}

function 升序() {
  const s = Sheets.Item(1);
  const r = s.Range("A1:C10");
  r.Sort(s.Range("B2"), 1);
}

function 两位小数() {
  const s = Sheets.Item(1);
  s.Range("A1:A10").NumberFormat = "0.00";
}

function 其他格式() {
  const s = Sheets.Item(1);
  s.Range("B1:B5").NumberFormat = "0.00%";
  s.Range("C1:C5").NumberFormat = "yyyy-mm-dd";
}

function 涂红() {
  const s = Sheets.Item(1);
  s.Range("A1").Interior.Color = RGB(255, 0, 0);
}

function 条件上色() {
  const s = Sheets.Item(1);
  for (let i = 2; i <= 10; i++) {
    const v = s.Range("B" + i).Value2;
    if (v < 60) {
      s.Range("B" + i).Interior.Color = RGB(255, 0, 0);
    }
  }
}

function 画框() {
  const s = Sheets.Item(1);
  const r = s.Range("A1:C3");
  r.Borders.LineStyle = 1;
  r.Borders.Weight = 2;
}

function 外框() {
  const s = Sheets.Item(1);
  const r = s.Range("A1:C3");
  r.BorderAround(1, 4);
}
